html.theme-dark .idphoto-drop,.idphoto-preview{background:#0f172a;border-color:#475569}@media(max-width:800px){.idphoto-grid{grid-template-columns:1fr}.idphoto-preview{min-height:280px}}@media(max-width:460px){.idphoto-options,.idphoto-results,.idphoto-card-fields{grid-template-columns:1fr}.idphoto-card-fields .wide{grid-column:auto}.idphoto-range{grid-template-columns:76px 1fr 38px}}
