<script>
(()=>{'use strict';
const MAX_FILE_BYTES=40*1024*1024,MAX_SOURCE_PIXELS=50000000,MAX_OUTPUT_PIXELS=30000000,DPI=300,allowedTypes=new Set(['image/jpeg','image/png','image/webp']),presets={one:[25,35],smallOne:[22,32],two:[35,49],smallTwo:[35,45],largeOne:[33,48],largeTwo:[35,53],social:[26,32],graduate:[41,55]},$=id=>document.getElementById(id),px=mm=>Math.round(mm/25.4*DPI),readable=bytes=>(bytes/1024).toFixed(1)+' KB';let source=null,photoBlob=null,cardBlob=null,photoUrl='',cardUrl='';
function status(text,type=''){$('status').textContent=text;$('status').className='idphoto-status '+type}function revoke(url){if(url)URL.revokeObjectURL(url)}function release(){revoke(photoUrl);revoke(cardUrl);photoUrl='';cardUrl='';photoBlob=null;cardBlob=null;$('downloadPhoto').disabled=true;$('downloadCard').disabled=true;$('resultPanel').hidden=true}
function outputSize(){let size=presets[$('preset').value];if(!size)size=[Number($('customWidth').value),Number($('customHeight').value)];const [w,h]=size.map(Number);if(!Number.isFinite(w)||!Number.isFinite(h)||w<10||w>80||h<10||h>100)throw new Error('自定义尺寸请填写宽 10–80 mm、高 10–100 mm。');const width=px(w),height=px(h);if(width*height>MAX_OUTPUT_PIXELS)throw new Error('输出尺寸过大。');return {mmWidth:w,mmHeight:h,width,height}}
async function decode(file){if('createImageBitmap'in window){const bitmap=await createImageBitmap(file,{imageOrientation:'from-image'});return {image:bitmap,width:bitmap.width,height:bitmap.height,close:()=>bitmap.close()}}const url=URL.createObjectURL(file);try{const image=await new Promise((resolve,reject)=>{const item=new Image();item.onload=()=>resolve(item);item.onerror=()=>reject(new Error('无法读取图片'));item.src=url});return {image,width:image.naturalWidth,height:image.naturalHeight,close:()=>URL.revokeObjectURL(url)}}catch(error){URL.revokeObjectURL(url);throw error}}
const toBlob=canvas=>new Promise((resolve,reject)=>canvas.toBlob(blob=>blob?resolve(blob):reject(new Error('浏览器无法生成图片')),'image/jpeg',.92));
function drawCover(ctx,x,y,width,height){const scale=Number($('scale').value)/100,ratio=Math.max(width/source.width,height/source.height)*scale,drawW=source.width*ratio,drawH=source.height*ratio;ctx.save();ctx.filter='brightness('+$('brightness').value+'%) contrast('+$('contrast').value+'%) saturate('+$('saturation').value+'%)';ctx.drawImage(source.image,x+(width-drawW)/2+Number($('offsetX').value)/100*width,y+(height-drawH)/2+Number($('offsetY').value)/100*height,drawW,drawH);ctx.restore()}
function drawPhoto(canvas,ctx,size){ctx.fillStyle=$('background').value;ctx.fillRect(0,0,size.width,size.height);ctx.imageSmoothingEnabled=true;ctx.imageSmoothingQuality='high';drawCover(ctx,0,0,size.width,size.height)}
function cardSize(){const layout=$('cardLayout').value;if(layout==='portrait')return {width:px(54),height:px(86),name:'竖版 54 × 86 mm'};if(layout==='landscape')return {width:px(86),height:px(54),name:'横版 86 × 54 mm'};const mmWidth=Number($('cardWidth').value),mmHeight=Number($('cardHeight').value);if(!Number.isFinite(mmWidth)||!Number.isFinite(mmHeight)||mmWidth<30||mmWidth>200||mmHeight<30||mmHeight>200)throw new Error('自定义工牌请填写宽、高各 30–200 mm。');return {width:px(mmWidth),height:px(mmHeight),name:'自定义 '+mmWidth+' × '+mmHeight+' mm'}}
function drawCard(canvas,ctx,card){const portrait=card.height>=card.width,color=$('cardColor').value;ctx.fillStyle=color;ctx.fillRect(0,0,card.width,card.height);ctx.fillStyle='rgba(255,255,255,.09)';ctx.beginPath();ctx.arc(card.width*(portrait?.1:.95),card.height*(portrait?.82:.1),card.width*.5,0,Math.PI*2);ctx.fill();const title=$('cardTitle').value.trim()||'工作证',name=$('photoName').value.trim()||'未填写',number=$('employeeNo').value.trim(),department=$('department').value.trim(),job=$('jobTitle').value.trim(),photo=portrait?{x:card.width*.22,y:card.height*.23,w:card.width*.56,h:card.height*.31}:{x:card.width*.08,y:card.height*.22,w:card.width*.31,h:card.height*.57};ctx.fillStyle='#fff';ctx.fillRect(photo.x-px(1),photo.y-px(1),photo.w+px(2),photo.h+px(2));ctx.save();ctx.beginPath();ctx.rect(photo.x,photo.y,photo.w,photo.h);ctx.clip();drawCover(ctx,photo.x,photo.y,photo.w,photo.h);ctx.restore();ctx.fillStyle='#fff';ctx.textAlign=portrait?'center':'left';ctx.font='700 '+Math.round(card.width*(portrait?.09:.055))+'px sans-serif';ctx.fillText(title,portrait?card.width/2:card.width*.48,portrait?card.height*.14:card.height*.22);const textX=portrait?card.width/2:card.width*.48,textY=portrait?card.height*.62:card.height*.43;ctx.font='600 '+Math.round(card.width*(portrait?.055:.045))+'px sans-serif';ctx.fillText(name,textX,textY);ctx.font='400 '+Math.round(card.width*(portrait?.031:.026))+'px sans-serif';const rows=[department?'部门：'+department:'',job?'职务：'+job:'',number?'工号：'+number:''];rows.filter(Boolean).forEach((row,index)=>ctx.fillText(row,textX,textY+card.height*(portrait?.075:.12)*(index+1)));const lineY=textY+card.height*(portrait?.075:.12)*(Math.max(1,rows.filter(Boolean).length)+.55);ctx.strokeStyle='rgba(255,255,255,.55)';ctx.lineWidth=Math.max(1,card.width*.004);ctx.beginPath();ctx.moveTo(portrait?card.width*.20:card.width*.48,lineY);ctx.lineTo(portrait?card.width*.80:card.width*.91,lineY);ctx.stroke()}
async function render(){if(!source)return;let size;try{size=outputSize()}catch(error){status(error.message,'error');return}release();try{const photoCanvas=document.createElement('canvas');photoCanvas.width=size.width;photoCanvas.height=size.height;drawPhoto(photoCanvas,photoCanvas.getContext('2d'),size);photoBlob=await toBlob(photoCanvas);photoUrl=URL.createObjectURL(photoBlob);$('photoResult').src=photoUrl;$('photoInfo').textContent=size.mmWidth+' × '+size.mmHeight+' mm · '+size.width+' × '+size.height+' px · '+readable(photoBlob.size);$('downloadPhoto').disabled=false;const cardEnabled=$('makeCard').checked;$('cardResultWrap').hidden=!cardEnabled;if(cardEnabled){const card=cardSize();if(card.width*card.height>MAX_OUTPUT_PIXELS)throw new Error('工牌尺寸过大。');const cardCanvas=document.createElement('canvas');cardCanvas.width=card.width;cardCanvas.height=card.height;drawCard(cardCanvas,cardCanvas.getContext('2d'),card);cardBlob=await toBlob(cardCanvas);cardUrl=URL.createObjectURL(cardBlob);$('cardResult').src=cardUrl;$('cardInfo').textContent=card.name+' · '+card.width+' × '+card.height+' px · '+readable(cardBlob.size);$('downloadCard').disabled=false}const preview=document.createElement('canvas'),ratio=Math.min(1,280/size.width,540/size.height);preview.width=Math.max(1,Math.round(size.width*ratio));preview.height=Math.max(1,Math.round(size.height*ratio));drawPhoto(preview,preview.getContext('2d'),{width:preview.width,height:preview.height});$('preview').replaceChildren(preview);$('resultPanel').hidden=false;status(cardEnabled?'已生成证件照和工牌。':'已生成证件照。','success')}catch(error){status(error.message||'生成失败。','error')}}
function loadFile(file){if(!file)return;if(!allowedTypes.has(file.type)||file.size>MAX_FILE_BYTES){status('请选择不超过 40 MB 的 JPG、PNG 或 WebP 图片。','error');return}release();if(source)source.close();status('正在读取照片…');decode(file).then(result=>{if(result.width*result.height>MAX_SOURCE_PIXELS||result.width>16384||result.height>16384){result.close();throw new Error('原图尺寸过大，最多 5000 万像素且单边不超过 16384 px。')}source=result;$('resetPosition').disabled=false;render()}).catch(error=>status(error.message||'照片读取失败。','error'))}
function download(blob,name){if(!blob)return;const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000)}function updateRange(id,out){$(out).textContent=id==='scale'?$(id).value+'%':$(id).value;render()}
$('photoFile').addEventListener('change',event=>loadFile(event.target.files[0]));['dragenter','dragover'].forEach(type=>$('dropZone').addEventListener(type,event=>{event.preventDefault();$('dropZone').classList.add('dragging')}));['dragleave','drop'].forEach(type=>$('dropZone').addEventListener(type,event=>{event.preventDefault();$('dropZone').classList.remove('dragging')}));$('dropZone').addEventListener('drop',event=>loadFile(event.dataTransfer.files[0]));$('preset').addEventListener('change',()=>{const custom=$('preset').value==='custom';$('customWidthWrap').hidden=!custom;$('customHeightWrap').hidden=!custom;render()});$('makeCard').addEventListener('change',()=>{$('cardFields').hidden=!$('makeCard').checked;render()});$('cardLayout').addEventListener('change',()=>{const custom=$('cardLayout').value==='custom';$('cardWidthWrap').hidden=!custom;$('cardHeightWrap').hidden=!custom;render()});['background','customWidth','customHeight','cardColor','cardWidth','cardHeight','photoName','employeeNo','department','jobTitle','cardTitle'].forEach(id=>$(id).addEventListener('input',render));[['scale','scaleOut'],['offsetX','offsetXOut'],['offsetY','offsetYOut'],['brightness','brightnessOut'],['contrast','contrastOut'],['saturation','saturationOut']].forEach(([id,out])=>$(id).addEventListener('input',()=>updateRange(id,out)));$('resetPosition').addEventListener('click',()=>{['scale','offsetX','offsetY'].forEach(id=>$(id).value=id==='scale'?100:0);$('scaleOut').textContent='100%';$('offsetXOut').textContent='0';$('offsetYOut').textContent='0';render()});$('downloadPhoto').addEventListener('click',()=>download(photoBlob,'证件照.jpg'));$('downloadCard').addEventListener('click',()=>download(cardBlob,'工作证.jpg'));window.addEventListener('beforeunload',()=>{release();if(source)source.close()})})();
</script>
